 protected override void WndProc(ref Message message){base.WndProc(ref message);if(message.Msg==0x84&&WindowState==FormWindowState.Normal){long point=message.LParam.ToInt64();var local=PointToClient(new Point((short)(point&0xffff),(short)((point>>16)&0xffff)));const int edge=6;bool left=local.X<edge,right=local.X>=Width-edge,top=local.Y<edge,bottom=local.Y>=Height-edge;int hit=left&&top?13:right&&top?14:left&&bottom?16:right&&bottom?17:left?10:right?11:top?12:bottom?15:1;if(hit!=1)message.Result=(IntPtr)hit;}}
 sealed record ProcedureChoice(string Id,string Name){public override string ToString()=>Name;}
