 static void StyleTabs(TabControl tabs){tabs.DrawMode=TabDrawMode.OwnerDrawFixed;tabs.SizeMode=TabSizeMode.Fixed;tabs.ItemSize=new Size(120,36);tabs.DrawItem+=(_,e)=>{bool active=e.Index==tabs.SelectedIndex;using var bg=new SolidBrush(active?Color.FromArgb(80,83,86):Color.FromArgb(59,62,65));e.Graphics.FillRectangle(bg,e.Bounds);TextRenderer.DrawText(e.Graphics,tabs.TabPages[e.Index].Text,tabs.Font,e.Bounds,Color.Gainsboro,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(active){using var pen=new Pen(Color.FromArgb(255,145,24),2);e.Graphics.DrawLine(pen,e.Bounds.Left,e.Bounds.Bottom-1,e.Bounds.Right,e.Bounds.Bottom-1);}};}
 static void Theme(Control root){if(root is not GraphCanvas && root is not ImageCanvas){root.BackColor=Color.FromArgb(59,62,65);root.ForeColor=Color.Gainsboro;}if(root is DataGridView grid){grid.EnableHeadersVisualStyles=false;grid.BackgroundColor=Color.FromArgb(59,62,65);grid.GridColor=Color.FromArgb(43,43,43);grid.DefaultCellStyle.BackColor=Color.FromArgb(48,48,48);grid.DefaultCellStyle.ForeColor=Color.Gainsboro;grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(107,76,42);grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(48,50,52);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.Gainsboro;}foreach(Control child in root.Controls)Theme(child);}
 void RefreshPluginImages(){if(shellImages is null)return;foreach(Control old in shellImages.Controls.Cast<Control>().ToArray()){if(old is PictureBox p)p.Image?.Dispose();old.Dispose();}shellImages.Controls.Clear();var node=Selected();if(node is null||toolPlugins.Find(node.ModuleId)is not IToolImageListProvider)node=document.CurrentProcedure.Nodes.FirstOrDefault(n=>toolPlugins.Find(n.ModuleId)is IToolImageListProvider);if(node is null||toolPlugins.Find(node.ModuleId)is not IToolImageListProvider provider)return;var entries=provider.GetImages(node);var caption=imageListPanel.Controls.OfType<Panel>().FirstOrDefault(p=>p.Dock==DockStyle.Top)?.Controls.OfType<Label>().FirstOrDefault();if(caption is not null)caption.Text=$"图像源 ({entries.Count(e=>e.Selected)}/{entries.Count})";foreach(var entry in entries){var picture=new PictureBox{Width=Px(72),Height=Px(52),SizeMode=PictureBoxSizeMode.Zoom,Margin=new Padding(Px(3)),BorderStyle=entry.Selected?BorderStyle.FixedSingle:BorderStyle.None};try{using var original=System.Drawing.Image.FromFile(Path.GetFullPath(entry.Path,document.BaseDirectory));picture.Image=new Bitmap(original);}catch(Exception ex)when(ex is IOException or ArgumentException or OutOfMemoryException){picture.BackColor=Color.FromArgb(80,50,50);}string nodeId=node.Id;picture.Click+=(_,_)=>Safe(()=>document.SetParameter(nodeId,"CurrentImagePath",JsonSerializer.SerializeToElement(entry.Path)));shellImages.Controls.Add(picture);}}
 void OpenToolDebug(){ApplyDraft();var node=Selected();if(node is null)return;var descriptor=registry.GetDescriptor(node);void Apply(Dictionary<string,JsonElement> values){document.SetParameters(node.Id,values);}async Task<NodeRunRecord> Execute(Dictionary<string,JsonElement> values){Apply(values);var ids=new HashSet<string>{node.Id};bool changed;do{changed=false;foreach(var c in document.CurrentProcedure.Connections)if(ids.Contains(c.ToNode))changed|=ids.Add(c.FromNode);foreach(var e in ProcedureGraph.ExecutionEdges(document.CurrentProcedure))if(ids.Contains(e.ToNode))changed|=ids.Add(e.FromNode);}while(changed);var p=document.CurrentProcedure;var subset=p with{Nodes=p.Nodes.Where(n=>ids.Contains(n.Id)).ToArray(),Connections=p.Connections.Where(c=>ids.Contains(c.FromNode)&&ids.Contains(c.ToNode)).ToArray(),ExecutionLinks=ProcedureGraph.ExecutionEdges(p).Where(e=>ids.Contains(e.FromNode)&&ids.Contains(e.ToNode)).ToArray()};var solution=document.Document with{Procedures=new[]{subset}};var session=await Task.Run(()=>new SolutionExecutor(registry).RunAsync(new SolutionWorkspace(solution,document.BaseDirectory),subset.Id));ShowRun(session);return session.Nodes.First(n=>n.NodeId==node.Id);}var sources=document.CurrentProcedure.Nodes.Where(n=>n.Id!=node.Id&&registry.GetDescriptor(n).Outputs.Any(p=>p.Kind==DataKind.GrayImage)).Select(n=>(n.Id,n.Name));if(toolPlugins.Find(node.ModuleId)is IWpfToolEditorFactory wpfFactory){var window=wpfFactory.CreateWpfEditor(new ToolEditorContext(node,document.BaseDirectory,Apply,Execute,document.CurrentProcedure.Nodes.ToList().FindIndex(n=>n.Id==node.Id)));_=new System.Windows.Interop.WindowInteropHelper(window){Owner=Handle};window.ShowDialog();return;}using Form dialog=toolPlugins.Find(node.ModuleId)?.CreateEditor(new ToolEditorContext(node,document.BaseDirectory,Apply,Execute,document.CurrentProcedure.Nodes.ToList().FindIndex(n=>n.Id==node.Id)))??new ToolDebugWindow(node,descriptor,ParameterLabels,Apply,Execute,sources,id=>{foreach(var c in document.CurrentProcedure.Connections.Where(c=>c.ToNode==node.Id&&c.ToPort=="Image").ToArray())document.Disconnect(c);document.BindInput(id,"Image",node.Id,"Image");},()=>InputImage(node.Id));dialog.ShowDialog(this);}
 void OpenParameters(){if(toolPlugins.Find(Selected()?.ModuleId??"") is not null){OpenToolDebug();return;}if(Selected()?.ModuleId is "vision.image-file" or "vision.threshold" or "vision.circle"){OpenToolDebug();return;}if(Selected() is null){status.Text="先选择需要配置的模块";return;}using var dialog=new Form(){Text=Selected()!.Name+" · 独立模块调试参数（非 VM 插件参数页）",Width=650,Height=520,StartPosition=FormStartPosition.CenterParent,Font=Font,BackColor=BackColor,ForeColor=ForeColor};dialog.Controls.Add(propertyPanel);dialog.Controls.Add(selectionLabel);dialog.FormClosing+=(_,e)=>{try{ApplyDraft();}catch(Exception ex){e.Cancel=true;MessageBox.Show(dialog,ex.Message,"参数未应用");}};dialog.ShowDialog(this);dialog.Controls.Remove(propertyPanel);dialog.Controls.Remove(selectionLabel);}
 void Safe(Action action){if(busy)return;try{action();}catch(Exception ex){status.Text=ex.Message;MessageBox.Show(this,ex.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
 void MarkDraft(){if(refreshing||selected is null||busy)return;draft=true;Title();}
 void Title()=>Text=$"{(document.IsDirty||draft?"* ":"")}{document.Document.Name} — 视觉流程编辑器";
 void DiscardDraft(){draft=false;ShowSelection();}
 void DocumentChanged(){results.Clear();graph.ClearStatuses();image.ClearImage();if(applying)return;RefreshDocument();status.Text="方案已修改 · 旧运行结果已清除";}
 void RefreshDocument(){refreshing=true;try{RefreshProcedureTabs();procedures.Items.Clear();foreach(var p in document.Document.Procedures)procedures.Items.Add(new ProcedureChoice(p.Id,p.Name));procedures.SelectedItem=procedures.Items.Cast<ProcedureChoice>().FirstOrDefault(p=>p.Id==document.CurrentProcedureId);graph.SetProcedure(document.CurrentProcedure);if(selected is not null&&!document.CurrentProcedure.Nodes.Any(n=>n.Id==selected))selected=null;graph.SelectNode(selected);Title();}finally{refreshing=false;}ShowSelection();}
 void RefreshProcedureTabs(){procedureTabs.SuspendLayout();var old=procedureTabs.Controls.Cast<Control>().ToArray();procedureTabs.Controls.Clear();foreach(var item in old)item.Dispose();foreach(var p in document.Document.Procedures){string id=p.Id;var holder=new FlowLayoutPanel{Width=Px(132),Height=Px(38),Margin=Padding.Empty,Padding=Padding.Empty,WrapContents=false,BackColor=id==document.CurrentProcedureId?Color.FromArgb(74,76,78):Color.FromArgb(59,62,65)};var tab=new Button{Text="● "+p.Name,Width=Px(82),Height=Px(38),FlatStyle=FlatStyle.Flat,BackColor=holder.BackColor,ForeColor=Color.Gainsboro,Margin=Padding.Empty,AutoEllipsis=true,Font=Font};tab.FlatAppearance.BorderSize=0;tab.Click+=(_,_)=>Safe(()=>SwitchProcedure(id));var context=new ContextMenuStrip();context.Items.Add("重命名",null,(_,_)=>Safe(()=>{string? name=AskName(p.Name);if(name is not null)document.RenameProcedure(id,name);}));context.Items.Add("复制流程",null,(_,_)=>Safe(()=>{ApplyDraft();document.DuplicateProcedure(id);}));context.Items.Add("删除流程",null,(_,_)=>Safe(()=>{ApplyDraft();document.DeleteProcedure(id);}));tab.ContextMenuStrip=context;tab.Disposed+=(_,_)=>context.Dispose();holder.Controls.Add(tab);var play=ShellIcon("flow_run.png","运行流程",24,38,holder.BackColor);play.Click+=async(_,_)=>{Safe(()=>SwitchProcedure(id));await RunAsync();};holder.Controls.Add(play);var repeat=ShellIcon("toolbar_toolbarRunRepeat_normal.png","连续运行",24,38,holder.BackColor);repeat.Enabled=false;holder.Controls.Add(repeat);procedureTabs.Controls.Add(holder);}procedureTabs.ResumeLayout();UpdateShellSelection();}

 void SwitchProcedure(string id){if(id==document.CurrentProcedureId)return;ApplyDraft();procedureViews[document.CurrentProcedureId]=(graph.GetViewport(),selected);procedureRuns[document.CurrentProcedureId]=(document.Revision,new(results,StringComparer.Ordinal),log.Text);selected=null;document.SelectProcedure(id);if(procedureRuns.TryGetValue(id,out var oldRun)&&oldRun.Revision==document.Revision){foreach(var pair in oldRun.Results){results[pair.Key]=pair.Value;graph.SetNodeStatus(pair.Key,pair.Value.Status);}log.Text=oldRun.Log;}else log.Clear();if(procedureViews.TryGetValue(id,out var saved)){graph.SetViewport(saved.View);selected=saved.Selected;graph.SelectNode(selected);ShowSelection();}else graph.FitToContent();}
 string? AskName(string initial){using var dialog=new Form(){Text="流程名称",Width=360,Height=150,StartPosition=FormStartPosition.CenterParent};var text=new TextBox(){Text=initial,Dock=DockStyle.Top};var ok=new Button(){Text="确定",Dock=DockStyle.Bottom,DialogResult=DialogResult.OK};dialog.Controls.Add(text);dialog.Controls.Add(ok);dialog.AcceptButton=ok;return dialog.ShowDialog(this)==DialogResult.OK?text.Text:null;}
 NodeDocument? Selected()=>document.CurrentProcedure.Nodes.FirstOrDefault(n=>n.Id==selected);
 void ShowSelection(){refreshing=true;try{parameters.Rows.Clear();outputs.Rows.Clear();var node=Selected();imageSource.Text=(node?.Name??document.CurrentProcedure.Nodes.FirstOrDefault(n=>n.ModuleId=="vision.image-file")?.Name??"图像源1")+".输出图像";propertyPanel.Enabled=node is not null&&!busy;selectionLabel.Text=node is null?"选择节点以编辑参数":node.Name;image.ClearImage();if(node is null){nodeName.Text="";return;}nodeName.Text=node.Name;enabledNode.Checked=node.Enabled;timeout.Value=Math.Clamp(node.TimeoutMs,0,int.MaxValue);ModuleDescriptor? descriptor=null;try{descriptor=registry.GetDescriptor(node);}catch(KeyNotFoundException){selectionLabel.Text=node.Name+" · 未安装模块";propertyPanel.Enabled=false;}
  if(descriptor is not null)foreach(var spec in descriptor.Parameters){string value=node.Parameters.TryGetValue(spec.Name,out var v)?v.ValueKind==JsonValueKind.String?v.GetString()??"":v.GetRawText():"";int row=parameters.Rows.Add(ParameterLabels.GetValueOrDefault(spec.Name,spec.Name),value);parameters.Rows[row].Tag=spec;parameters.Rows[row].Cells[0].ToolTipText=spec.Name+" · "+spec.Kind;}
  if(results.TryGetValue(node.Id,out var record)){foreach(var pair in record.Outputs)outputs.Rows.Add(pair.Key,Describe(pair.Value));var gray=record.Outputs.Values.FirstOrDefault(v=>v.Kind==DataKind.GrayImage)?.As<GrayImage>()??InputImage(node.Id);if(gray is not null){image.SetImage(gray);var circle=record.Outputs.Values.FirstOrDefault(v=>v.Kind==DataKind.Circle)?.As<CircleFit>();image.SetOverlay(null,circle.HasValue?new(CircleDetectionStatus.Success,circle,Array.Empty<Point2>(),0):null);}}
 }finally{refreshing=false;Title();UpdateShellSelection();RefreshPluginImages();}}
 GrayImage? InputImage(string id){foreach(var c in document.CurrentProcedure.Connections.Where(c=>c.ToNode==id))if(results.TryGetValue(c.FromNode,out var source)&&source.Outputs.TryGetValue(c.FromPort,out var value)&&value.Kind==DataKind.GrayImage)return value.As<GrayImage>();return null;}
 static string Describe(PortValue v)=>v.Kind switch{DataKind.GrayImage=>$"{v.As<GrayImage>().Width} × {v.As<GrayImage>().Height}",DataKind.Components=>$"{v.As<IReadOnlyList<Component>>().Count} 个区域",DataKind.Circle=>$"中心 ({v.As<CircleFit>().CenterX:F2}, {v.As<CircleFit>().CenterY:F2})，R={v.As<CircleFit>().Radius:F2}",DataKind.Boolean=>v.As<bool>()?"True":"False",_=>Convert.ToString(v.Value,CultureInfo.InvariantCulture)??""};
 void ApplyDraft(){parameters.EndEdit();if(!draft)return;var node=Selected()??throw new InvalidOperationException("请选择节点。");var values=new Dictionary<string,JsonElement>();foreach(DataGridViewRow row in parameters.Rows){var spec=(ParameterDescriptor)row.Tag!;string text=Convert.ToString(row.Cells[1].Value,CultureInfo.InvariantCulture)??"";object value=spec.Kind switch{ParameterKind.Text=>text,ParameterKind.Integer=>int.Parse(text,CultureInfo.InvariantCulture),ParameterKind.Number=>double.Parse(text,CultureInfo.InvariantCulture),ParameterKind.Boolean=>bool.Parse(text),_=>throw new InvalidDataException("未知参数类型")};values[spec.Name]=JsonSerializer.SerializeToElement(value);}applying=true;try{document.UpdateNode(node.Id,nodeName.Text,enabledNode.Checked,(int)timeout.Value,values);draft=false;}finally{applying=false;}RefreshDocument();}
 Dictionary<string,JsonElement> Defaults(ModuleDescriptor d){var p=d.Parameters.ToDictionary(s=>s.Name,s=>s.DefaultValue?.Clone()??JsonSerializer.SerializeToElement<object>(s.Kind switch{ParameterKind.Text=>"",ParameterKind.Boolean=>false,ParameterKind.Integer=>0,_=>0.0}));void Set(string name,object value){if(p.ContainsKey(name))p[name]=JsonSerializer.SerializeToElement(value);}Set("Threshold",128);Set("InitialRadius",50.0);Set("SearchHalfWidth",5.0);Set("SampleCount",64);Set("GradientThreshold",15.0);Set("Polarity","Both");Set("RadialStep",.5);Set("GradientHalfSpan",1.0);Set("MinimumEdges",6);Set("Operator",">");return p;}
 string AddModule(string id,double x,double y){ApplyDraft();var d=registry.Descriptors.First(m=>m.Id==id);string node=document.AddNode(d.Id,d.Version,x,y,Defaults(d));document.SetNodeName(node,ModuleLabels.GetValueOrDefault(id,d.DisplayName));selected=node;graph.SelectNode(node);ShowSelection();return node;}
 void ChooseImage(){var node=Selected();if(toolPlugins.Find(node?.ModuleId??"")is not null){OpenToolDebug();return;}if(node?.ModuleId!="vision.image-file")throw new InvalidOperationException("请先选择文件图像源节点。");ApplyDraft();using var dialog=new OpenFileDialog(){Filter="BMP 图像|*.bmp"};if(dialog.ShowDialog(this)==DialogResult.OK)document.SetParameter(node.Id,"Path",JsonSerializer.SerializeToElement(dialog.FileName));}
 bool ConfirmLeave(){parameters.EndEdit();if(!document.IsDirty&&!draft)return true;var answer=MessageBox.Show(this,"当前方案有未保存修改，是否保存？","保存方案",MessageBoxButtons.YesNoCancel);if(answer==DialogResult.Cancel)return false;if(answer==DialogResult.Yes)return Save(false);return true;}
 void New(){if(!ConfirmLeave())return;procedureViews.Clear();procedureRuns.Clear();selected=null;draft=false;document.NewSolution();}
 void Demo(){if(!ConfirmLeave())return;procedureViews.Clear();procedureRuns.Clear();selected=null;draft=false;document.Load(Path.Combine(AppContext.BaseDirectory,"demo.vmx.json"));graph.FitToContent();}
 void Open(){if(!ConfirmLeave())return;using var dialog=new OpenFileDialog(){Filter="独立流程方案|*.vmx.json|JSON|*.json"};if(dialog.ShowDialog(this)==DialogResult.OK){procedureViews.Clear();procedureRuns.Clear();document.Load(dialog.FileName);selected=null;draft=false;RefreshDocument();graph.FitToContent();}}
 bool Save(bool saveAs){ApplyDraft();string? path=document.FilePath;if(saveAs||path is null){using var dialog=new SaveFileDialog(){Filter="独立流程方案|*.vmx.json",FileName="solution.vmx.json"};if(dialog.ShowDialog(this)!=DialogResult.OK)return false;path=dialog.FileName;}document.Save(path);Title();status.Text="方案已保存";return true;}
 void AddProcedure(){ApplyDraft();procedureViews[document.CurrentProcedureId]=(graph.GetViewport(),selected);document.AddProcedure("流程 "+(document.Document.Procedures.Count+1));selected=null;RefreshDocument();}
 void ValidateProcedure(){ApplyDraft();var validation=document.Validate();log.Text=validation.IsValid?"流程校验通过。":string.Join(Environment.NewLine,validation.Issues.Select(i=>$"{i.NodeId}: {i.Message}"));status.Text=validation.IsValid?"流程校验通过":$"发现 {validation.Issues.Count} 个问题；请查看运行记录。";resultTabs.SelectedIndex=2;}
 void SetBusy(bool value){busy=value;foreach(var b in editingTools)b.Enabled=!value;run.Enabled=!value;stop.Enabled=value;toolbox.Enabled=!value;procedures.Enabled=!value;propertyPanel.Enabled=!value&&Selected() is not null;graph.ReadOnlyMode=value;}
 async Task RunAsync(){if(busy)return;try{ApplyDraft();if(document.CurrentProcedure.Nodes.Count==0)throw new InvalidOperationException("请先添加模块并连接流程。");var validation=document.Validate();if(!validation.IsValid){ValidateProcedure();return;}results.Clear();graph.ClearStatuses();image.ClearImage();log.Clear();using var cancel=new CancellationTokenSource();runningCancel=cancel;SetBusy(true);var workspace=new SolutionWorkspace(document.Document,document.BaseDirectory);string procedure=document.CurrentProcedureId;long runRevision=document.Revision;var progress=new Progress<ExecutionEvent>(e=>{if(!busy||document.Revision!=runRevision||document.CurrentProcedureId!=procedure)return;graph.SetNodeStatus(e.NodeId,e.Status);log.AppendText($"{e.NodeId} · {e.Status}{Environment.NewLine}");});var session=await Task.Run(()=>new SolutionExecutor(registry).RunAsync(workspace,procedure,progress,cancel.Token));ShowRun(session);}
 catch(Exception ex){status.Text="执行失败："+ex.Message;log.AppendText(ex.Message+Environment.NewLine);}finally{runningCancel=null;SetBusy(false);ShowSelection();if(closeAfterRun){closeAfterRun=false;BeginInvoke(new Action(Close));}}}
 void ShowRun(ExecutionSessionResult session){history.Rows.Add(history.Rows.Count+1,DateTime.Now.ToString("HH:mm:ss"),$"{document.CurrentProcedure.Name} · {session.Status} · {session.Nodes.Count} 个模块");results.Clear();foreach(var r in session.Nodes){results[r.NodeId]=r;graph.SetNodeStatus(r.NodeId,r.Status);}log.Text=string.Join(Environment.NewLine,session.Nodes.Select(n=>$"{document.CurrentProcedure.Nodes.First(x=>x.Id==n.NodeId).Name} · {n.Status} · {n.ElapsedMilliseconds:F1} ms{(n.Message is null?"":" · "+n.Message)}"));status.Text=$"流程执行完成：{session.Status} · 选择节点查看输出；执行完成不等于检测合格";ShowSelection();}
 void HandleClosing(object? sender,FormClosingEventArgs e){if(busy){e.Cancel=true;closeAfterRun=true;runningCancel?.Cancel();status.Text="正在停止后关闭…";return;}try{if(!ConfirmLeave())e.Cancel=true;}catch(Exception ex){e.Cancel=true;MessageBox.Show(this,ex.Message);}}

}












